    {
      "topic": {
        "text": "Rounding and casting numbers in Java",
        "refs": ["Q0000"]
      },
      "explanation_text": {
        "text": "Calling Math.round on a double returns a long value; to store it in an int you must explicitly cast because implicit casting cannot reduce the size from 8 bytes to 4 bytes.",
        "refs": ["Q0000", "Q0001"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Effect of casting before rounding",
        "refs": ["Q0002"]
      },
      "explanation_text": {
        "text": "Casting the result of Math.random() directly to int truncates the fractional part, yielding zero; the cast must be applied after multiplying by 100 and rounding the entire expression.",
        "refs": ["Q0002", "Q0003"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Formatting numbers as currency or percentages in Java",
        "refs": ["Q0004", "Q0005"]
      },
      "explanation_text": {
        "text": "Java's NumberFormat class (in java.text) provides methods to format numbers with locale‑specific symbols such as dollar signs, commas for thousands, and percent signs.",
        "refs": ["Q0004", "Q0005"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "Math.round returns a long value.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Implicit casting from long to int is not allowed because it would lose data; explicit casting is required.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Casting a double value between 0 and 1 directly to int yields 0.",
        "refs": ["Q0002"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [
    {
      "procedure_name": {
        "text": "Round a random double to an integer between 0 and 100",
        "refs": ["Q0000", "Q0001", "Q0003"]
      },
      "steps": [
        {
          "text": "Call Math.random() to obtain a double in [0,1).",
          "refs": ["Q0000"]
        },
        {
          "text": "Multiply the result by 100.",
          "refs": ["Q0000"]
        },
        {
          "text": "Wrap the multiplication in parentheses and pass it to Math.round().",
          "refs": ["Q0003"]
        },
        {
          "text": "Cast the long returned by Math.round() to int.",
          "refs": ["Q0001"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "This procedure yields an integer between 0 and 100 inclusive.",
        "refs": ["Q0003"]
      }
    },
    {
      "procedure_name": {
        "text": "Format a number as currency using NumberFormat",
        "refs": ["Q0004", "Q0005"]
      },
      "steps": [
        {
          "text": "Import java.text.NumberFormat.",
          "refs": ["Q0004"]
        },
        {
          "text": "Obtain a NumberFormat instance for currency with NumberFormat.getCurrencyInstance().",
          "refs": ["Q0004"]
        },
        {
          "text": "Call format(number) on the NumberFormat instance to produce a locale‑specific currency string.",
          "refs": ["Q0004"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "The resulting string includes a dollar sign and appropriate grouping separators.",
        "refs": ["Q0004"]
      }
    }
  ],
